module Mcp
  # A failure the model reads and can act on (generated by maquina:mcp).
  # Raised inside a tool, it becomes a tool result with isError: true and the
  # message as its text, not a JSON-RPC error: write the message for the model.
  #
  #   raise Mcp::ToolError, "status must be draft or published"
  #   raise Mcp::ToolError.not_found
  class ToolError < StandardError
    # One message for a record that does not exist and for one that belongs to
    # someone else, so the tools never tell a caller which ids exist.
    NOT_FOUND = "Not found: no record with that id is available to this connection."

    def self.not_found
      new(NOT_FOUND)
    end
  end
end
